"""
# As amlodipine besylate is a drug, we can find the corresponding information in the prescriptions database.
prescriptions_db = LoadDB('prescriptions')
filtered_prescriptions_db = FilterDB(prescriptions_db, 'DRUG=amlodipine besylate||STARTDATE like 2105%')
subject_id_list = GetValue(filtered_prescriptions_db, 'SUBJECT_ID, list')

# For these patients, we need to find the other drugs they were prescribed at the same time.
drug_count = {}
for subject_id in subject_id_list:
    filtered_prescriptions_db = FilterDB(prescriptions_db, 'SUBJECT_ID={}||STARTDATE like 2105%'.format(subject_id))
    drug_list = GetValue(filtered_prescriptions_db, 'DRUG, list')
    for drug in drug_list:
        if drug != 'amlodipine besylate':
            if drug in drug_count:
                drug_count[drug] += 1
            else:
                drug_count[drug] = 1

# We need to count the frequency of each drug and find the top three frequently prescribed drugs.
top_three_drugs = sorted(drug_count, key=drug_count.get, reverse=True)[:3]
answer = top_three_drugs
